def generate(seed):
    r = random.Random(seed)
    n = r.choice((2, 2, 3, 3, 4, 4, 5))
    for _ in range(400):
        G = min(8, n + r.choice((1, 2, 3, 4)))
        L = r.choice((4, 5, 6, 7)) * 4
        gaps = [2] * G
        if r.random() < 0.55:
            gaps[r.randrange(G)] = 1
        hits = [1] * (G + 1)
        left = L - sum(gaps) - sum(hits)
        if left < 0:
            continue
        slots = [(0, i) for i in range(G)] * 3 + [(1, i) for i in range(G + 1)] * 2
        r.shuffle(slots)
        for kind, i in slots:
            if left <= 0:
                break
            if kind == 0 and gaps[i] < 5:
                gaps[i] += 1
                left -= 1
            elif kind == 1 and hits[i] < 3:
                hits[i] += 1
                left -= 1
        if left > 0 or max(gaps) < 3 or len(set(gaps)) < 2:
            continue
        K = ""
        for i in range(G):
            K += "x" * hits[i] + "." * gaps[i]
        K += "x" * hits[G]
        if n in (G, G + 1, K.count("x"), max(gaps)):
            continue
        return K + "/" + str(n)
    return "x..xx...x.xx..x.x..xx.xx/3"

