NAMES = (("kick", "snare", "hat"), ("bass", "clap", "shaker"), ("boom", "bang", "tss"),
 ("drum", "clap", "tap"), ("K", "S", "H"), ("1", "2", "3"), ("bd", "sn", "hh"),
