def sp(row, ch):
 out, i, n = [], 0, len(row)
 while i < n:
  if row[i] == ch:
   j = i
   while j < n and row[j] == ch:
    j += 1
   out.append((i, j))
   i = j
  else:
   i += 1
 return out

def cov(K, R, gp):
 return sum(1 for a, b in gp if all(R[i] == "x" for i in range(a, b)))

def build(K, gp, ch, r, d, hd=0.0):
 # a row exactly filling every hole in `ch`, with deliberate near-misses in the rest
 L = len(K)
 row = ["."] * L
 keep = set()

 def put(a, b):
  for i in range(a, b):
   row[i] = "x"
  keep.update(range(a, b))
  if a:
   keep.add(a - 1)
  if b < L:
   keep.add(b)

 def free(a, b):
  return all(i not in keep for i in range(a, b))

 for g in ch:
  put(*g)
 rest = [g for g in gp if g not in ch]
 r.shuffle(rest)
 mode = {}
 for m in (("short", "spill", "spill") if r.random() < 0.5 else ("spill", "short", "spill")):
  for g in rest:
   if g not in mode and (m == "spill" or g[1] - g[0] > 1):
    mode[g] = m
    break
 for j, g in enumerate(rest):
  m = mode.get(g) or (r.choice(("short", "multi", "edge")) if j < 2 and r.random() < 0.3 else "none")
  a, b = g
  w = b - a
  if m == "spill":
   if free(a, b) and a and (a - 1) not in keep:
    put(a - 1, b)
    continue
   if free(a, b) and b < L and b not in keep:
    put(a, b + 1)
    continue
   m = "short"
  if not free(a, b):
   continue
  if m == "short" and w > 1:
   l = r.randint(1, w - 1)
   o = r.randint(0, w - l)
   put(a + o, a + o + l)
  elif m == "multi" and w > 2:
   put(a, a + 1)
   put(a + 2, b)
  elif m == "edge" and w > 1:
   put(a, b - 1) if r.random() < 0.5 else put(a + 1, b)
 for _ in range(10 if r.random() < 0.6 else 0):    # a run as long as a hole, in the wrong place
  l = r.choice([b - a for a, b in gp])
  p = r.randrange(0, L - l + 1)
  if (p, p + l) not in gp and free(max(p - 1, 0), min(p + l + 1, L)):
   put(p, p + l)
   break
 for i in range(L):
  if i not in keep and r.random() < (d if K[i] == "x" else hd):
   row[i] = "x"
 s = "".join(row)
 return None if any(g in gp and g not in ch for g in sp(s, "x")) else s

def ok(K, S, H, gp, n, lvl):
 L = len(K)
 gs = set(gp)
 gl = {b - a for a, b in gp}
 rS, rH = sp(S, "x"), sp(H, "x")
 fS = [g for g in rS if g in gs]
 fH = [g for g in rH if g in gs]
 if len(fS) != n or not fH:
  return False
 ins = [g for g in rS if g not in gs and any(a <= g[0] and g[1] <= b for a, b in gp)]
 sam = [g for g in rS if g not in gs and (g[1] - g[0]) in gl]
 cS = cov(K, S, gp)
 if not (ins or cS > n):
  return False
 if lvl == 0 and (not sam or not ins or cS <= n or max(b - a for a, b in fS) < 3):
  return False
 hit = lambda R, a, b: any(R[i] == "x" for i in range(a, b))
 col = lambda k: sum(1 for i in range(L) if [K[i], S[i], H[i]].count("x") == k)
 riv = [len(rS), S.count("x"), len(fH), len(ins), cS, len(set(fS) | set(fH)), len(fS) + len(fH),
           sum(1 for a, b in gp if hit(S, a, b)), sum(1 for a, b in gp if hit(H, a, b)),
           sum(1 for i in range(L) if S[i] == "x" and K[i] == "."),
           sum(1 for i in range(L) if S[i] == K[i] == "x")]
 if lvl:
  return all(v != n for v in riv)
 riv += [len(sam), len(rH), H.count("x"), cov(K, H, gp), col(2), col(3),
   sum(1 for i in range(L) if S[i] == H[i] == "x")]
 return all(v != n for v in riv)

def rend(K, S, H, r):
 nm = r.choice(NAMES)
 w = max(len(x) for x in nm)
 bar = r.random() < 0.85
 out = []
 if bar and r.random() < 0.35:
  out.append(" " * (w + 2) + "    ".join(str(i + 1) for i in range(len(K) // 4)))
 for a, row in zip(nm, (K, S, H)):
  b = "|" + "|".join(row[i:i + 4] for i in range(0, len(K), 4)) + "|" if bar else row
  out.append((a.rjust(w) + " " + b).rstrip())
 return "\n".join(out)

def solve(clue):
 K, ns = clue.split("/")
 n = int(ns)
 r = random.Random(clue)
 gp = sp(K, ".")
 big = max(range(len(gp)), key=lambda i: gp[i][1] - gp[i][0])
 for t in range(600):
  idx = list(range(len(gp)))
  r.shuffle(idx)
  if r.random() < 0.9:
   idx.remove(big)
   idx.insert(r.randrange(n), big)
  S = build(K, gp, [gp[i] for i in idx[:n]], r, r.choice((0.05, 0.12, 0.2)))
  if S is None:
   continue
  for _ in range(3):
   e = r.choice([x for x in (1, 2, 3) if x != n and x + n <= len(gp)] or [1])
   H = build(K, gp, [gp[i] for i in idx[n:n + e]], r, r.choice((0.3, 0.45, 0.6)), r.choice((0.35, 0.5)))
   if H is not None and ok(K, S, H, gp, n, t // 250):
    out = rend(K, S, H, r)
    R = [l for l in (re.sub("[^x.]", "", l) for l in out.split("\n")) if l]
    if len(R) == 3 and R[0] == K and len(set(map(len, R))) == 1:
     return out
 S = ["."] * len(K)
 H = list(S)
 for a, b in gp[:n]:
  S[a:b] = "x" * (b - a)
 a, b = gp[-1]
 H[a:b] = "x" * (b - a)
 return rend(K, "".join(S), "".join(H), r)

